public static class DmDiagnosticsTest {
    static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
    static void Check(bool ok,string why){if(!ok)throw new Exception("DM diagnostics: "+why);}
    static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}
    static string Metric(DiagnosticUiSnapshot s,string n){return s.Pages.SelectMany(p=>p.Panels).SelectMany(p=>p.Metrics).First(m=>m.Label==n).Value;}
    static DmDiagnosticInput Fixture(){string peer=new string('b',64),call=new string('a',32),share=new string('c',32);return new DmDiagnosticInput{Scope="isolated-profile/account:72/auth:1",Name="Sample peer",Sample=true,Control="Sample authenticated TLS epoch 1/winner 7 (not media)",Voice=new VoiceDiagnosticsData{Active=true,CallId=call,PeerId=peer,VerifiedPeerId=peer,Lifetime=2,MediaGeneration=1,MediaState=2,CallState="Connected",StartedUtc=DateTime.UtcNow.AddSeconds(-20).ToString("o"),InputDevice="Sample microphone",OutputDevice="Sample output",MediaRoute="TURN Relay",Native="receive_call_id="+call+"\nreceive_call_lifetime=2\nreceive_media_generation=1\nreceive_remote_peer_id="+peer+"\ncall_media_state=2\nmedia_session_id=100\ncodec=Opus\nmedia_state=connected\ntrack_open=true\nopus_encoded_bytes=1000\nrtp_observed_bytes=2000\nrtp_arrival_jitter_ms=4\nneteq_current_delay_ms=40\nneteq_target_delay_ms=60\nneteq_concealment_events=2\nneteq_concealed_samples=320\naec_enabled=true\naec_render_reference_active=true\naec_delay_ms=30\naec_reference_underruns=0\nselected_ice_pair=sample relay pair\nice_connection_state=connected\nice_dtls_srtp_state=connected\nlatest_audio_error=none\nlatest_media_error=none\nperf_opus_encode=count:50;last_us:90;max_us:190;mean_us:100;deadline_misses:0"},ScreenId=share,ScreenPeer=peer,ScreenLifetime=3,ScreenGeneration=1,ScreenState=4,ScreenRaw="share_id="+share+"\nexpected_peer_id="+peer+"\nshare_lifetime=3\nmedia_generation=1\nreceiver_callback_owner=sender\nlocal_track_direction=sendonly\nactive_backend=WebRTC Compatibility\ncodec=H.264\nnegotiated_codec=H.264\nencoder=Sample software H.264 encoder\nrequested_fps=30\ncapture_fps=30\nencode_fps=29\ntransmitted_fps_send_api=29\neffective_encoded_mbps_send_api=2.4\nmedia_connected=true\ntrack_open=true\nselected_ice_pair=sample screen ICE pair\nmedia_stack=WebRTC ICE / DTLS-SRTP / H.264 RTP\nrecovery_trigger=none\nmedia_failure_reason=none\nencoded_queue_depth=1\npending_capture_frame=0\ndropped_before_encode=1\ndropped_encoded_queue=0"};}
    static void ProjectionTests(){
        var i=Fixture();var id=DmDiagnosticIdentity.Select(i,i.Voice.CallId);var h=new DmDiagnosticHistory();bool current,v,s;DmDiagnosticProjection.Bind(id,i,out current,out v,out s);Check(current&&v&&s,"combined exact owner binding");var snap=DmDiagnosticProjection.Read(id,i,h);Check(Metric(snap,"Voice / screen activity").Contains("Local sharer")&&Metric(snap,"Captured FPS")=="30"&&Metric(snap,"Presented FPS").Contains("sender"),"sharer local not invented viewer");
        i.ScreenPeer=new string('d',64);DmDiagnosticProjection.Bind(id,i,out current,out v,out s);Check(v&&!s,"different peer share never associated");i.ScreenPeer=id.Peer;i.Voice.Native=i.Voice.Native.Replace("receive_media_generation=1","receive_media_generation=0");DmDiagnosticProjection.Bind(id,i,out current,out v,out s);Check(current&&!v&&s,"stale voice generation rejected independently of screen");i=Fixture();id=DmDiagnosticIdentity.Select(i,i.ScreenId);i.Voice.Active=false;snap=DmDiagnosticProjection.Read(id,i,h);Check(Metric(snap,"Voice / screen activity").Contains("No matching voice")&&Metric(snap,"Captured FPS")=="30","screen-only");
        i=Fixture();id=DmDiagnosticIdentity.Select(i,i.Voice.CallId);i.ScreenState=0;snap=DmDiagnosticProjection.Read(id,i,h);Check(Metric(snap,"Voice / screen activity").Contains("Bound voice")&&Metric(snap,"Captured FPS").Contains("N/A"),"voice-only");
        i=Fixture();id=DmDiagnosticIdentity.Select(i,i.Voice.CallId);DateTime now=DateTime.UtcNow.AddSeconds(-700);h.Observe(id,i,now);Check(!h.Current.VoiceEncoded.HasValue,"no fabricated first rate");i.Voice.Native=i.Voice.Native.Replace("opus_encoded_bytes=1000","opus_encoded_bytes=101000").Replace("rtp_observed_bytes=2000","rtp_observed_bytes=202000");h.Observe(id,i,now.AddSeconds(1));Check(h.Current.VoiceEncoded.HasValue&&h.Current.VoiceRtp.HasValue&&Math.Abs(h.Current.VoiceEncoded.Value-.8)<1e-9&&Math.Abs(h.Current.VoiceRtp.Value-1.6)<1e-9,"actual counter delta semantics");h.Observe(id,i,now.AddSeconds(2));Check(h.Current.VoiceEncoded==0,"stalls zero");i.Voice.MediaGeneration=2;i.Voice.Native=i.Voice.Native.Replace("receive_media_generation=1","receive_media_generation=2");h.Observe(id,i,now.AddSeconds(3));Check(!h.Current.VoiceEncoded.HasValue,"recovery generation rebaseline");
        for(int n=4;n<700;n++)h.Observe(id,i,now.AddSeconds(n));Check(h.Points.Count==300&&h.Events.Count<=64,"bounded RAM");h.Paused=true;int count=h.Points.Count;h.Observe(id,i,DateTime.UtcNow);Check(h.Points.Count==count,"pause graph collection not current snapshot");
        i.Scope="another-profile";snap=DmDiagnosticProjection.Read(id,i,h);Check(snap.Banner.Contains("No active")&&!Metric(snap,"Events").Contains("isolated-profile"),"profile data invalidation");i=Fixture();i.Voice.Native+="\nselected_ice_pair=password=private123 token=private456";Check(!DmDiagnosticProjection.Export(DmDiagnosticProjection.Read(DmDiagnosticIdentity.Select(i,""),i,null)).Contains("private"),"safe export");
        i=Fixture();id=DmDiagnosticIdentity.Select(i,i.ScreenId);i.Voice.Active=false;i.ScreenRaw=i.ScreenRaw.Replace("receiver_callback_owner=sender","receiver_callback_owner=remote track").Replace("local_track_direction=sendonly","local_track_direction=recvonly")+"\nreceived_fps_access_units=28\nrendered_fps=27\ndecoded_frames=30\ndecoder_queue_depth=1\ndecoder_oldest_queue_age_ms=12";h.Clear();h.Observe(id,i,DateTime.UtcNow.AddSeconds(-2));i.ScreenRaw=i.ScreenRaw.Replace("decoded_frames=30","decoded_frames=55");h.Observe(id,i,DateTime.UtcNow.AddSeconds(-1));snap=DmDiagnosticProjection.Read(id,i,h);Check(Metric(snap,"Captured FPS").Contains("not local")&&Metric(snap,"Received complete access-unit FPS")=="28"&&Metric(snap,"Presented FPS")=="27"&&h.Current.DecodedFps>24,"viewer frame distinction and delta decode");
        i=Fixture();id=DmDiagnosticIdentity.Select(i,"");i.Voice.MediaState=3;i.ScreenState=5;DmDiagnosticProjection.Bind(id,i,out current,out v,out s);Check(current&&!v&&!s&&Metric(DmDiagnosticProjection.Read(id,i,h),"Voice media lifecycle").Contains("Recovering"),"retained connected snapshots rejected during recovery");i=Fixture();id=DmDiagnosticIdentity.Select(i,"");i.Voice.Native=i.Voice.Native.Replace("call_media_state=2","call_media_state=3");DmDiagnosticProjection.Bind(id,i,out current,out v,out s);Check(!v&&s,"native interrupted snapshot rejected even before managed transition");
        i=Fixture();id=DmDiagnosticIdentity.Select(i,"");h.Clear();var tick=DateTime.UtcNow.AddSeconds(-2);h.Observe(id,i,tick);i.Voice.Native=i.Voice.Native.Replace("opus_encoded_bytes=1000","opus_encoded_bytes=101000");h.Observe(id,i,tick.AddSeconds(1));i.Voice.MediaGeneration=2;i.Voice.Native=i.Voice.Native.Replace("receive_media_generation=1","receive_media_generation=2");Check(Metric(DmDiagnosticProjection.Read(id,i,h),"Local encoded Opus rate (before send)").Contains("Waiting"),"no old-generation rate shown before next observer tick");
        i=Fixture();i.ScreenId=i.Voice.CallId;Check(DmDiagnosticIdentity.Select(i,"share:"+i.ScreenId).Screen&&DmDiagnosticIdentity.Select(i,i.Voice.CallId).Screen==false,"explicit call/share namespace even for colliding IDs");
        var benchmark=System.Diagnostics.Stopwatch.StartNew();i=Fixture();id=DmDiagnosticIdentity.Select(i,"");for(int n=0;n<200;n++)DmDiagnosticProjection.Read(id,i,null);benchmark.Stop();Console.WriteLine("DM projection benchmark: 200 active fixture projections mean_ms="+(benchmark.Elapsed.TotalMilliseconds/200).ToString("0.###"));
        Console.WriteLine("PASS: exact call/share/profile/lifetime/generation ownership; voice-only/share-only/combined; foreign snapshots rejected; sharer/viewer; rates/zero/reset; bounded graph/pause; privacy.");
    }
    static void Capture(Window w,string path){w.UpdateLayout();var surface=(FrameworkElement)w.Content;var bitmap=new RenderTargetBitmap((int)Math.Ceiling(surface.ActualWidth),(int)Math.Ceiling(surface.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(surface),null,new Rect(0,0,surface.ActualWidth,surface.ActualHeight));bitmap.Render(drawing);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(path))png.Save(file);}
    public static async Task Run(DesktopApplication desktop,string directory){
        ProjectionTests();var originalRevision=(ulong)Get(desktop,"authenticatedFriendSnapshotGeneration");var originalSession=(ulong)Get(desktop,"discoverySessionGeneration");string scope=(string)Call(desktop,"DmDiagnosticScope");Set(desktop,"authenticatedFriendSnapshotGeneration",originalRevision+1);Check((string)Call(desktop,"DmDiagnosticScope")==scope,"friend refresh is not call authentication replacement");Set(desktop,"discoverySessionGeneration",originalSession+1);Check((string)Call(desktop,"DmDiagnosticScope")!=scope,"real authentication lifetime invalidates diagnostics");Set(desktop,"authenticatedFriendSnapshotGeneration",originalRevision);Set(desktop,"discoverySessionGeneration",originalSession);
        string call=((ChatViewModel)Get(desktop,"model")).VoiceCallId;var input=Fixture();Set(desktop,"dmDiagnosticTestInput",new Func<DmDiagnosticInput>(()=>input));
        try{
            input.Voice.Active=false;input.ScreenState=0;Call(desktop,"OpenContextDiagnostics",DiagnosticSection.DirectMessageCalls,"");await Task.Delay(1200);Check(((DiagnosticUiSnapshot)Get(desktop,"dmViewSnapshot")).Banner.Contains("No active"),"empty DM view");input.Voice.Active=true;input.ScreenState=4;await Task.Delay(1300);Check(((DiagnosticUiSnapshot)Get(desktop,"dmViewSnapshot")).Banner.Contains("Connected"),"call start observed while idle view open");
            Call(desktop,"OpenContextDiagnostics",DiagnosticSection.DirectMessageCalls,input.Voice.CallId);var window=(Window)Get(desktop,"groupDiagnosticWindow");var tabs=(TabControl)Get(desktop,"groupDiagnosticTabs");window.Width=1250;window.Height=920;Check(tabs.Items.Count==6&&((ComboBox)Get(desktop,"diagnosticExamples")).Visibility==Visibility.Collapsed,"live DM navigation no sample selector");Call(desktop,"OpenContextDiagnostics",DiagnosticSection.DirectMessageCalls,input.Voice.CallId);Check(Object.ReferenceEquals(window,Get(desktop,"groupDiagnosticWindow")),"single detachable window");
            await Task.Delay(2200);for(int n=0;n<4;n++){tabs.SelectedIndex=n;window.UpdateLayout();Capture(window,Path.Combine(directory,"dm-"+new[]{"overview","voice","screen","network"}[n]+"-FIXTURE.png"));}
            var scroll=((TabItem)tabs.Items[3]).Content;await Task.Delay(1300);Check(Object.ReferenceEquals(scroll,((TabItem)tabs.Items[3]).Content),"live refresh preserves controls/scroll");var history=(DmDiagnosticHistory)Get(desktop,"dmHistory");Set(desktop,"dmGraphsPaused",true);history.Paused=true;int count=history.Points.Count;await Task.Delay(1200);Check(count==history.Points.Count,"UI pause only history");Set(desktop,"dmGraphsPaused",false);await Task.Delay(1200);Check(history.Points.Count>count,"resume sampling");
            foreach(double scale in new[]{1.0,1.25,1.5,2.0}){window.Width=640;window.Height=480;((FrameworkElement)window.Content).LayoutTransform=new ScaleTransform(scale,scale);window.UpdateLayout();Check(tabs.ActualWidth>0,"small/scaled view");}((FrameworkElement)window.Content).LayoutTransform=Transform.Identity;
            input.Voice.CallId=new string('e',32);await Task.Delay(1300);Check(((DiagnosticUiSnapshot)Get(desktop,"dmViewSnapshot")).Banner.Contains("No active"),"new call does not replace exact selected session");input.Scope="switched-profile";await Task.Delay(1300);Check(history.Points.Count==0&&history.Events.Count==0,"UI profile history cleared");window.Close();Check(((System.Collections.Generic.List<Action>)Get(desktop,"dmViewRefreshes")).Count==0&&history.Points.Count==0,"unsubscribe/release on close");
        }finally{Set(desktop,"dmDiagnosticTestInput",null);var w=(Window)Get(desktop,"groupDiagnosticWindow");if(w!=null)w.Close();}
        Call(desktop,"OpenContextDiagnostics",DiagnosticSection.DirectMessageCalls,"");var real=(DiagnosticUiSnapshot)Get(desktop,"dmViewSnapshot");Check(!real.Sample&&real.Banner.Contains("No active"),"real packaged native idle collector is not a fixture");Check(!((string)Call(desktop,"CurrentDiagnosticExport")).Contains("SAMPLE FIXTURE"),"normal export no fixture");((Window)Get(desktop,"groupDiagnosticWindow")).Close();Check(((ChatViewModel)Get(desktop,"model")).VoiceCallId==call,"diagnostics never started/replaced call");Console.WriteLine("PASS: packaged WPF DM contextual entry, in-place refresh, pause/resume, resize/scaling, selected-call/profile invalidation, cleanup and real idle provider. Screenshots are explicitly labeled fixtures, not physical acceptance.");
    }
}
